const $=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,n=3)=>v==null?'不适用':Number(v).toFixed(n),pct=v=>v==null?'不适用':fmt(100*v,1)+'%';
function table(head,rows){return `<div class="scroll"><table><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v??'不适用'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function canvas(id,image){const c=$(id);c.width=image.width;c.height=image.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.putImageData(new ImageData(new Uint8ClampedArray(image.pixels),image.width,image.height),0,0);return c;}
function readCanvas(id){const c=$(id);return{pixels:c.getContext('2d',{willReadFrequently:true}).getImageData(0,0,c.width,c.height).data,width:c.width,height:c.height};}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);}
function matrix(m,names,method='model'){return '<div class="matrix heat-matrix">'+table(['真值↓ / 预测→',...names,'拒判','召回'],m.matrix.map((row,c)=>{const total=row.reduce((a,b)=>a+b,0);return[esc(names[c]),...row.map((n,j)=>{const alpha=total?n/total:0,hue=j===c?'40,124,120':j===names.length?'105,117,130':'184,93,81';return `<button data-cell="${method},${c},${j}" style="background:rgba(${hue},${.06+.64*alpha});color:#163b3d" title="${esc(names[c])} → ${esc(names[j]??'拒判')}：${n} / ${total}" aria-label="${esc(names[c])}预测为${esc(names[j]??'拒判')} ${n}例">${n}</button>`;}),pct(m.perClass[c].recall)];}))+'<p class="fine">颜色深浅表示该真值行中的占比；青色为对角线、赭红为误判、灰色为拒判。点击格子回查样本。</p></div>';}
function cards(items){return `<div class="metricgrid">${items.map(([title,value,detail])=>`<div class="metric"><span>${esc(title)}</span><b>${value}</b><span>${esc(detail??'')}</span></div>`).join('')}</div>`;}
function bar(values,names){const colors=g.S17Teach.rockColors;return `<div class="stack" role="img" aria-label="${esc(names.join('、'))}">${values.map((v,i)=>`<span style="width:${(v??0)*100}%;background:${colors[i%colors.length]}" title="${esc(names[i])} ${pct(v)}">${v>.08?pct(v):''}</span>`).join('')}</div><p class="fine">${names.map((n,i)=>`${esc(n)} ${pct(values[i])}`).join(' · ')}</p>`;}
function source(id,version,type,content){return{sourceRecordId:id,sourceVersion:version,sourceType:type,content};}
function claim(id,statement,sourceRecordId,sourceVersion,selector,extra={}){return{claimId:id,revision:sourceVersion,kind:'model_inference',statement,sourceRefs:[{sourceRecordId,sourceVersion,selector}],reviewStatus:'unreviewed',traceabilityStatus:'linked',supportStatus:'unchecked',reviewHistory:[],...extra};}
function envelope(caseId,version,run,content){return{schemaVersion:'1.0',caseId,caseVersion:version,runId:run.runId,datasetId:'s17-synthetic-v1',wellId:'DEMO-017',dataNature:'synthetic_teaching',runConfig:{seed:run.seed??17,dataVersion:run.dataVersion??'s17-synthetic-v1',splitDescription:run.split??'independent grouped training / validation / test',method:run.method,parameters:run.config,inputRevision:run.revision},...content};}
